 void refreshApps(){if(loadingApps)return;loadingApps=true;new Thread(()->{ArrayList<Entry> result=new ArrayList<>();HashSet<String> seen=new HashSet<>();seen.add(getPackageName());for(String cat:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER}){for(ResolveInfo r:getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(cat),0)){String pkg=r.activityInfo.packageName;if(r.activityInfo.enabled&&seen.add(pkg))result.add(new Entry(r.loadLabel(getPackageManager()).toString(),pkg,appIcon(pkg)));}}result.sort((a,b)->java.text.Collator.getInstance(new Locale("ru")).compare(a.name,b.name));h.post(()->{allApps=result;loadingApps=false;rebuildExtras();if(active)screen.invalidate();});}).start();}
