 void loadFavorites(){if(prefs.contains("favorites")){try{JSONArray a=new JSONArray(prefs.getString("favorites",""));String[] saved=new String[6];if(a.length()!=6)throw new IllegalArgumentException();HashSet<String> unique=new HashSet<>();for(int i=0;i<6;i++){saved[i]=a.getString(i);if(saved[i].isEmpty()||saved[i].equals(getPackageName())||!unique.add(saved[i]))throw new IllegalArgumentException();}System.arraycopy(saved,0,pkgs,0,6);}catch(Exception ignored){}}else{pkgs[3]=prefs.getBoolean("smarttube",true)?"org.smarttube.stable":"com.google.android.youtube.tv";prefs.edit().putString("favorites",new JSONArray(Arrays.asList(pkgs)).toString()).apply();}refreshFavoriteVisuals();}
