 void pickFavorite(final int slot){if(loadingApps){Toast.makeText(this,"Список приложений обновляется — повторите через секунду",0).show();return;}final ArrayList<Entry> choices=new ArrayList<>(allApps);String[] labels=new String[choices.size()];for(int i=0;i<choices.size();i++){Entry e=choices.get(i);int position=Arrays.asList(pkgs).indexOf(e.pkg);labels[i]=e.name+(position>=0?" · место "+(position+1):"");}new AlertDialog.Builder(this).setTitle("Выберите приложение для места "+(slot+1)).setItems(labels,(d,n)->{String pkg=choices.get(n).pkg;if(getPackageManager().getLeanbackLaunchIntentForPackage(pkg)==null&&getPackageManager().getLaunchIntentForPackage(pkg)==null){Toast.makeText(this,"Приложение больше недоступно",0).show();refreshApps();return;}int existing=Arrays.asList(pkgs).indexOf(pkg);if(existing>=0){String old=pkgs[slot];pkgs[existing]=old;}pkgs[slot]=pkg;saveFavorites();}).setNegativeButton("Отмена",null).show();}
