 void toggleVpn(){if(vpnToggle.pending)return;refreshNetwork();if(!vpnKnown){Toast.makeText(this,"Не удалось определить состояние VPN",0).show();openHapp();return;}vpnToggle.begin(vpnActive,SystemClock.elapsedRealtime());String action=vpnToggle.target?"connect_without_ui":"disconnect_without_ui";Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("happ://"+action)).setPackage("su.happ.proxyutility");try{if(i.resolveActivity(getPackageManager())==null)throw new ActivityNotFoundException();startActivity(i);h.removeCallbacks(vpnCheck);h.postDelayed(vpnCheck,500);}catch(Exception e){vpnToggle.cancel();Toast.makeText(this,"Команда недоступна — открою Happ",0).show();openHapp();}screen.invalidate();}
