 void youtubeSettings(){int minutes=prefs.getInt("youtube_minutes",5);new AlertDialog.Builder(this).setTitle("YouTube · @ProskurninLife").setItems(new String[]{"Счётчик: "+(prefs.getBoolean("youtube_enabled",true)?"вкл":"выкл"),"Интервал: "+minutes+" мин","О счётчике"},(d,n)->{if(n==0){prefs.edit().putBoolean("youtube_enabled",!prefs.getBoolean("youtube_enabled",true)).apply();fetchYoutube();screen.invalidate();}else if(n==1){final int[] choices={5,10,15,30,60};new AlertDialog.Builder(this).setTitle("Обновлять не чаще чем раз в…").setItems(new String[]{"5 минут","10 минут","15 минут","30 минут","60 минут"},(dd,k)->{prefs.edit().putInt("youtube_minutes",choices[k]).apply();fetchYoutube();}).setNegativeButton("Отмена",null).show();}else new AlertDialog.Builder(this).setTitle("Публичный счётчик").setMessage("YouTube округляет публичное число подписчиков. Динамика — разница с последним сохранённым замером за вчера (UTC), а не история из API. Если замера нет, динамика скрыта.  Обновление зависит от YouTube. При отсутствии сети показываем последнее значение до суток. Время последнего обновления показано ниже. Недельный прирост отключён.\n\nДля отзыва ключа: Google Cloud → APIs & Services → Credentials. Для отключения достаточно выключить счётчик здесь."+youtubeUpdated()).setPositiveButton("Закрыть",null).show();}).setNegativeButton("Закрыть",null).show();}
 void fetchYoutube(){if(!active||youtubeBusy||!prefs.getBoolean("youtube_enabled",true))return;int minutes=prefs.getInt("youtube_minutes",5);long interval=Math.max(300000L,minutes*60000L),now=System.currentTimeMillis(),last=prefs.getLong("youtube_attempt",0);if(now>=last&&now-last<interval)return;youtubeBusy=true;prefs.edit().putLong("youtube_attempt",now).apply();new Thread(()->{try{JSONObject result=ApiClient.request(this,"youtube/channel?interval="+(interval/1000),null);prefs.edit().putString("youtube_data",result.toString()).putBoolean("youtube_error",result.optBoolean("stale",false)).apply();android.util.Log.i("ProskurninAPI","YouTube counter updated via RU -> US");}catch(Exception ignored){prefs.edit().putBoolean("youtube_error",true).apply();}finally{h.post(()->{youtubeBusy=false;if(active)screen.invalidate();});}},"youtube-counter").start();}
 void quick(){int action=quickAction(topIndex);if(action==0)sources();else if(action==1)openIntent(new Intent("android.settings.WIFI_SETTINGS"));else if(action==3)profile();else if(action==4)toggleVpn();else if(action==5)startActivity(new Intent(this,MovieActivity.class));else new AlertDialog.Builder(this).setCustomTitle(versionTitle("Настройки")).setItems(new String[]{"Настройки телевизора","Оформление экрана","Погода и поставщики","Кнопка VPN: "+(prefs.getBoolean("vpn_button",true)?"вкл":"выкл"),"Приложения главного экрана","Счётчик YouTube","AI-подбор: "+(prefs.getBoolean("ai_enabled",true)?"вкл":"выкл"),"Кнопка помощника: "+(prefs.getBoolean("voice_key_enabled",true)?"вкл":"выкл"),"Диалог с AI","Заставка","Пульт с телефона"},(d,n)->{if(n==0)openIntent(new Intent("android.settings.SETTINGS"));else if(n==1)settings();else if(n==2)weatherSettings();else if(n==3){prefs.edit().putBoolean("vpn_button",!prefs.getBoolean("vpn_button",true)).apply();topIndex=Math.min(topIndex,quickCount()-1);screen.invalidate();}else if(n==4)chooseFavoriteSlot();else if(n==5)youtubeSettings();else if(n==7){prefs.edit().putBoolean("voice_key_enabled",!prefs.getBoolean("voice_key_enabled",true)).apply();}else if(n==8)startActivity(new Intent(this,AssistantActivity.class));else if(n==9)dreamMenu();else if(n==10)openIntent(new Intent().setClassName("local.proskurnin.remote","local.proskurnin.remote.RemoteActivity"));else{prefs.edit().putBoolean("ai_enabled",!prefs.getBoolean("ai_enabled",true)).apply();topIndex=Math.min(topIndex,quickCount()-1);screen.invalidate();}}).setNegativeButton("Закрыть",null).show();}

 final Runnable tick=new Runnable(){public void run(){if(!active)return; updateTime(); refreshNetwork(); loadBackground(); fetchWeather();fetchRates();fetchYoutube();screen.invalidate();h.postDelayed(this,60000-System.currentTimeMillis()%60000);}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setBackgroundDrawable(new ColorDrawable(0xff10141d));getWindow().getDecorView().setSystemUiVisibility(5894);prefs=getSharedPreferences("preview",0);speed=new NetworkSpeedProbe(this,()->{if(active)screen.invalidate();});if(prefs.contains("yandex_key"))prefs.edit().remove("yandex_key").apply();if(prefs.contains("weather_value")&&System.currentTimeMillis()-prefs.getLong("weather_time",0)<21600000)weather=prefs.getString("weather_value",weather)+"\nОбновление…";screen=new Screen();setContentView(screen);for(int i=0;i<6;i++){try{Drawable d=getPackageManager().getApplicationIcon(pkgs[i]);Bitmap bi=Bitmap.createBitmap(144,144,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bi);d.setBounds(0,0,144,144);d.draw(c);icons[i]=bi;}catch(Exception ignored){}}}
 protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.hasCategory(Intent.CATEGORY_HOME)){drawer=false;top=false;updateSpeedFocus();screen.invalidate();}}
 public void onBackPressed(){drawer=false;top=false;updateSpeedFocus();screen.invalidate();}
 protected void onResume(){super.onResume();active=true;statsReader=new DeviceStats(this);h.removeCallbacks(statsTick);h.post(statsTick);loadFavorites();watchNetwork();if(vpnToggle.pending){h.removeCallbacks(vpnCheck);h.post(vpnCheck);}refreshApps();refreshNetwork();for(int i=0;i<6;i++)installed[i]=getPackageManager().getLeanbackLaunchIntentForPackage(pkgs[i])!=null||getPackageManager().getLaunchIntentForPackage(pkgs[i])!=null;h.post(tick);fetchWeather();}
 protected void onPause(){active=false;updateSpeedFocus();h.removeCallbacks(statsTick);unwatchNetwork();h.removeCallbacks(vpnCheck);generation++;h.removeCallbacks(tick);bg=null;period="";super.onPause();}
 protected void onDestroy(){h.removeCallbacks(statsTick);statsWorker.shutdownNow();super.onDestroy();}
 void watchNetwork(){if(networkCallback!=null)return;networkCallback=new ConnectivityManager.NetworkCallback(){void changed(){h.post(()->{if(active){refreshNetwork();screen.invalidate();}});}public void onAvailable(Network n){changed();}public void onLost(Network n){changed();}public void onCapabilitiesChanged(Network n,NetworkCapabilities cap){changed();}};try{((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).registerDefaultNetworkCallback(networkCallback);}catch(Exception e){networkCallback=null;}}
 void unwatchNetwork(){if(networkCallback!=null){try{((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).unregisterNetworkCallback(networkCallback);}catch(Exception ignored){}networkCallback=null;}}
 void fetchRates(){long now=System.currentTimeMillis();if(!active||ratesBusy||now-ratesAttempt<300000)return;ratesAttempt=now;ratesBusy=true;new Thread(()->{try{if(System.currentTimeMillis()-prefs.getLong("fiat_at",0)>21600000){try{String[] r=RatesClient.fiat();prefs.edit().putString("USD",r[0]).putString("EUR",r[1]).putString("CNY",r[2]).putString("fiat_date",r[3]).putLong("fiat_at",System.currentTimeMillis()).apply();}catch(Exception ignored){}}if(active){try{double btc=RatesClient.bitcoin();prefs.edit().putString("BTC_USD",String.valueOf(btc)).putLong("btc_usd_at",System.currentTimeMillis()).apply();}catch(Exception ignored){}}}finally{if(active)fetchRateHistory();h.post(()->{ratesBusy=false;if(active)screen.invalidate();});}},"rates").start();}
 String historyKey(int i){return historyKey(i,RatesTrend.yesterday(System.currentTimeMillis()));}
 String historyKey(int i,String day){boolean cbr=i<3&&prefs.getString("fiat_date","").startsWith("ЦБ");return "history_"+new String[]{"USD","EUR","CNY","BTC_USD"}[i]+"_"+(cbr?"CBR":"Coinbase")+"_"+day;}
 void fetchRateHistory(){
  long now=System.currentTimeMillis();int days=prefs.getBoolean("rates_chart",true)?6:1;
  boolean cbr=prefs.getString("fiat_date","").startsWith("ЦБ");
  for(int offset=0;offset<days&&active;offset++){
   if(offset>0&&!prefs.getBoolean("rates_chart",true))break;
   String day=RatesTrend.yesterday(now-offset*86400000L);
   boolean missing=false;for(int i=0;i<3;i++)if(!prefs.contains(historyKey(i,day)))missing=true;
   if(cbr&&missing&&now-prefs.getLong("history_attempt_CBR_"+day,0)>3600000){
    prefs.edit().putLong("history_attempt_CBR_"+day,now).apply();try{String[] date=day.split("-");String[] values=RatesClient.cbr("?date_req="+date[2]+"/"+date[1]+"/"+date[0]);SharedPreferences.Editor edit=prefs.edit();for(int i=0;i<3;i++)edit.putString("history_"+new String[]{"USD","EUR","CNY"}[i]+"_CBR_"+day,values[i]);edit.apply();}catch(Exception ignored){}
   }
   for(int i=cbr?3:0;i<4&&active;i++){
    String key=historyKey(i,day);if(prefs.contains(key)||now-prefs.getLong("attempt_"+key,0)<3600000)continue;
    prefs.edit().putLong("attempt_"+key,now).apply();try{double value=RatesClient.previous(new String[]{"USD","EUR","CNY","BTC"}[i],false,day);prefs.edit().putString(key,String.valueOf(value)).apply();}catch(Exception ignored){}
   }
  }
  String cutoff=RatesTrend.yesterday(now-7L*86400000);SharedPreferences.Editor edit=prefs.edit();for(String key:prefs.getAll().keySet())if((key.startsWith("history_")||key.startsWith("attempt_history_"))&&key.length()>10&&key.substring(key.length()-10).compareTo(cutoff)<0)edit.remove(key);edit.apply();
 }

 void updateTime(){Date now=new Date();SimpleDateFormat f=new SimpleDateFormat(prefs.getBoolean("clock24",true)?"HH:mm":"h:mm a",new Locale("ru"));clock=f.format(now);date=new SimpleDateFormat("EEEE, d MMMM",new Locale("ru")).format(now);}
 void loadBackground(){if(!prefs.getBoolean("background",true)||!prefs.getBoolean("design",true)){bg=null;period="";return;}int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);String p=hour<6||hour>=22?"night":hour<11?"morning":hour<17?"day":"evening";if(p.equals(period))return;period=p;final int token=++generation;new Thread(()->{Bitmap result=null;try(InputStream in=getAssets().open("backgrounds/"+p+".jpg")){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;result=BitmapFactory.decodeStream(in,null,o);}catch(Exception|OutOfMemoryError e){}final Bitmap ready=result;h.post(()->{if(active&&token==generation){bg=ready;screen.invalidate();}});}).start();}
 void fetchWeather(){if(!active||weatherBusy||System.currentTimeMillis()-weatherAt<weatherInterval)return;weatherBusy=true;weatherAt=System.currentTimeMillis();final int token=weatherGeneration;new Thread(()->{WeatherClient.Result result=null;try{result=WeatherClient.fetch(new File(getFilesDir(),"weather-routing.json"),prefs.getBoolean("weather_server",true),()->active);}catch(Exception ignored){}final WeatherClient.Result ready=result;h.post(()->{weatherBusy=false;if(token!=weatherGeneration){weatherAt=0;if(active)fetchWeather();return;}if(ready!=null){prefs.edit().putString("weather_value",ready.text).putInt("weather_kind",ready.kind).putBoolean("weather_night",ready.night).putString("weather_wind",String.valueOf(ready.wind)).putLong("weather_time",System.currentTimeMillis()).apply();weather=ready.text;weatherInterval=1800000;android.util.Log.i("ProskurninWeather","Updated via "+ready.source);}else{weatherInterval=300000;long time=prefs.getLong("weather_time",0),age=System.currentTimeMillis()-time;weather=age>=0&&age<21600000?prefs.getString("weather_value","")+" · нет обновления с "+new SimpleDateFormat("HH:mm",new Locale("ru")).format(new Date(time)):"Москва · погода недоступна";if(!active)weatherAt=0;}if(active)screen.invalidate();});},"weather").start();}
