 void settings(){
  ArrayList<String> items=new ArrayList<>(Arrays.asList("Новое оформление: "+(prefs.getBoolean("design",true)?"вкл":"выкл"),"Фон по времени суток: "+(prefs.getBoolean("background",true)?"вкл":"выкл"),"Часы: "+(prefs.getBoolean("clock24",true)?"24 часа":"12 часов"),"Открыть прежний главный экран"));
  if(!nativeHome()){items.add("Резервный автозапуск: "+(prefs.getBoolean("boot_home",true)?"вкл":"выкл"));items.add("Обработка кнопки Home");}
  final int chartIndex=items.size();items.add("Графики валют за 7 дней: "+(prefs.getBoolean("rates_chart",true)?"вкл":"выкл"));
  new AlertDialog.Builder(this).setCustomTitle(versionTitle("Оформление экрана")).setItems(items.toArray(new String[0]),(d,n)->{
   if(n==chartIndex){boolean on=!prefs.getBoolean("rates_chart",true);prefs.edit().putBoolean("rates_chart",on).apply();if(on){ratesAttempt=0;fetchRates();}screen.invalidate();return;}
   if(n==3){openIntent(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName("com.google.android.tvlauncher","com.google.android.tvlauncher.MainActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return;}
   if(n==4){prefs.edit().putBoolean("boot_home",!prefs.getBoolean("boot_home",true)).apply();return;}
   if(n==5){openIntent(new Intent("android.settings.ACCESSIBILITY_SETTINGS"));return;}
   String key=n==0?"design":n==1?"background":"clock24";prefs.edit().putBoolean(key,!prefs.getBoolean(key,true)).apply();generation++;period="";updateTime();loadBackground();screen.invalidate();
  }).setNegativeButton("Закрыть",null).show();
 }

 public boolean onKeyDown(int code,KeyEvent e){if(code==KeyEvent.KEYCODE_MENU){if(e.getRepeatCount()==0)settings();return true;}if(code==23||code==66){if(e.getRepeatCount()==0){longPress=false;e.startTracking();}return true;}if(code==4&&drawer){drawer=false;screen.invalidate();return true;}if(code>=19&&code<=22){if(drawer){if(code==19){if(extraIndex<6){selected=Math.min(5,extraIndex);drawer=false;}else extraIndex-=6;}if(code==20&&extraIndex+6<extras.size())extraIndex+=6;else if(code==20&&extraIndex/6<(extras.size()-1)/6)extraIndex=extras.size()-1;if(code==21&&extraIndex%6>0)extraIndex--;if(code==22&&extraIndex%6<5&&extraIndex+1<extras.size())extraIndex++;}else if(top){if(code==21)topIndex=Math.max(0,topIndex-1);if(code==22)topIndex=Math.min((quickCount()-1),topIndex+1);if(code==20)top=false;}else{if(code==21)selected=Math.max(0,selected-1);if(code==22)selected=Math.min(5,selected+1);if(code==19){top=true;topIndex=Math.min((quickCount()-1),selected*quickCount()/6);}if(code==20){drawer=true;extraIndex=Math.max(0,Math.min(selected,extras.size()-1));}}updateSpeedFocus();android.util.Log.i("ProskurninPreview","focus="+(drawer?"apps:"+extraIndex:top?"quick:"+topIndex:pkgs[selected]));screen.invalidate();return true;}return super.onKeyDown(code,e);}
 public boolean onKeyLongPress(int code,KeyEvent e){if(code==23||code==66){longPress=true;if(!top&&!drawer)editFavorite(selected);else if(top&&quickAction(topIndex)==5)startActivity(new Intent(this,AssistantActivity.class));else settings();return true;}return super.onKeyLongPress(code,e);}
 public boolean onKeyUp(int code,KeyEvent e){if(code==23||code==66){if(!longPress&&!e.isCanceled()){if(top)quick();else launch();}return true;}return super.onKeyUp(code,e);}
